        agent_body._state = {'last_tx': 0.0, 'last_ty': 0.0, 'tvx': 0.0, 'tvy': 0.0}
    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()

    # Check corridor bounds
    x_min, x_max = sandbox.get_corridor_bounds()

    # Update target position with corridor constraints
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        state['tvx'] = 0.5 * state['tvx'] + 0.5 * (tx - state['last_tx']) / dt
        state['tvy'] = 0.5 * state['tvy'] + 0.5 * (ty - state['last_ty']) / dt
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)

    # Adjust target position to stay within corridor bounds
    if step_count < 110:
        # Initial phase: move toward corridor and activation zone
        if sx < x_min - 0.02:
            gx = x_min
        elif sx > x_max + 0.02:
            gx = x_max
        else:
            gx = 11.95
        gy = 1.35
    elif in_slot:
        # In rendezvous slot: use target position
        gx, gy = tx, ty
    else:
        # Phase after slot: move toward activation zone
        if (step_count // 120) % 2 == 0:
            gx = 13.1
        else:
            gx = 13.5
        # Ensure target x is within corridor bounds
        if gx < x_min:
            gx = x_min
        elif gx > x_max:
            gx = x_max
        gy = 1.35

    # Adjust target position to stay within corridor bounds
    if gx < x_min:
        gx = x_min
    elif gx > x_max:
        gx = x_max

    # Calculate force vector with corridor constraints
    if in_slot:
        fx = 300.0 * (gx - sx) + 60.0 * (state['tvx'] - svx)
        fy = 300.0 * (gy - sy) + 60.0 * (state['tvy'] - svy)
    else:
        fx = 300.0 * (gx - sx) - 60.0 * svx
        fy = 180.0 * (gy - sy) - 45.0 * svy

    # Ensure force magnitude doesn't exceed max thrust
    mag = math.sqrt(fx*fx + fy*fy)
    if mag > 119.0:
